export function studioLabGuide(studioSlug: string, labSlug: string) {
  const studio = STATISTICS_STUDIOS.find(s => s.slug === studioSlug), lab = studio?.labs.find(l => l.slug === labSlug)
  const entry = STUDIO_GUIDE_ENTRIES[studioSlug]?.[labSlug]
  return lab && entry ? makeGuide(lab.title, entry) : undefined
}
